#!/usr/bin/env node

/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs each filename it would apply in order.
 */

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

async function main() {
  // Check if migrations directory exists
  try {
    const files = await fs.promises.readdir(migrationsDir);

    // Filter for SQL files and sort them to ensure proper order
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in', migrationsDir);
      return;
    }

    console.log('Found migration files:');
    sqlFiles.forEach(file => {
      const fullPath = path.join(migrationsDir, file);
      console.log(`Would apply: ${file}`);
    });

    console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
    } else {
      console.error('Error reading migrations directory:', error);
    }
    process.exit(1);
  }
}

// Execute the main function
main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

